package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.FamilyNameVO;

class FamilyNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of family name of user profile")
  void test_family_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    FamilyNameValueHolder<Object> value = new FamilyNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.familyName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getFamilyNameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getFamilyName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.familyNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getFamilyNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getFamilyName().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of family name of user profile")
  void test_family_name_value_holder_assign_value_object() {
    Object holder = new Object();
    FamilyNameValueHolder<Object> value = new FamilyNameValueHolder<>(holder);
    FamilyNameVO vo = FamilyNameVO.from("one");
    Assertions.assertFalse(value.getFamilyNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.familyName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getFamilyNameValue().orElseThrow());
    Assertions.assertSame(holder, value.familyName(Optional.empty()));
    Assertions.assertFalse(value.getFamilyNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.familyName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getFamilyNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of family name of user profile against the original")
  void test_family_name_value_holder_read() {
    Object holder = new Object();
    FamilyNameValueHolder<Object> value = new FamilyNameValueHolder<>(holder);
    FamilyNameVO vo = FamilyNameVO.from("one");
    FamilyNameVO other = FamilyNameVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getFamilyNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readFamilyName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readFamilyName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.familyName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readFamilyName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readFamilyName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of family name of user profile")
  void test_family_name_value_holder_unset() {
    Object holder = new Object();
    FamilyNameValueHolder<Object> value = new FamilyNameValueHolder<>(holder);
    FamilyNameVO vo = FamilyNameVO.from("one");
    value.familyName(vo);
    Assertions.assertSame(holder, value.unsetFamilyNameIfMatches("familyName_other"));
    Assertions.assertTrue(value.getFamilyNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetFamilyNameIfMatches("familyName"));
    Assertions.assertFalse(value.getFamilyNameValue().isPresent(),
        "The field name must clear the value");
    value.familyName(vo);
    Assertions.assertSame(holder, value.unsetFamilyName());
    Assertions.assertFalse(value.getFamilyNameValue().isPresent(), "Unset must clear the value");
  }
}
